<?php
 namespace Pterodactyl\Services\Dezerx\DiscordBot; use SodiumException; class Signature { public const WINDOW = 600; public static function verify(string $publicKey, string $signature, string $timestamp, string $body): bool { if (!function_exists('sodium_crypto_sign_verify_detached')) { return false; } if (strlen($publicKey) !== 64 || !ctype_xdigit($publicKey) || strlen($signature) !== 128 || !ctype_xdigit($signature)) { return false; } if (!ctype_digit($timestamp) || abs(time() - (int) $timestamp) > self::WINDOW) { return false; } try { return sodium_crypto_sign_verify_detached(hex2bin($signature), $timestamp . $body, hex2bin($publicKey)); } catch (SodiumException) { return false; } } } 